-- =============================================================
-- V10 批量演示数据：按三级类目铺开的商品 / 用户 / 行为
-- 本文件由 sql/tools/gen_bulk_data.py 生成，请勿手改
--
-- ⚠️ 执行方式（必须带 --default-character-set=utf8mb4）
--   mysql --default-character-set=utf8mb4 -u root -p recommend_db \
--     < sql/migration/V10__bulk_demo_data.sql
--
-- 规模：商品 4500（150 个三级类目 × 30），用户 500，行为见文件末尾统计
--
-- 回滚（按 id 区间精确删除，不影响原有数据）：
--   DELETE FROM `behavior` WHERE id >= 8229;
--   DELETE FROM `user`     WHERE id >= 202;
--   DELETE FROM `product`  WHERE id >= 501;
-- =============================================================

USE recommend_db;

-- ---------- 0. 把 seed 里的「演示商品 N」改成按类目命名并重定价 ----------
-- 必须重定价：seed 的价格是 10~5000 随机撒的，
-- 只改名会出现「苹果平板 ¥46.90」这种明显不合理的数据。
UPDATE `product` p
JOIN `category` c3 ON c3.`id` = p.`category_id`
JOIN `category` c2 ON c2.`id` = c3.`parent_id`
JOIN `category` c1 ON c1.`id` = c2.`parent_id`
SET p.`name`        = CONCAT(c3.`name`, ' 精选款 ', p.`id`),
    p.`subtitle`    = CONCAT(c1.`name`, ' · ', c2.`name`),
    p.`description` = CONCAT('本商品属于', c1.`name`, '下的', c2.`name`,
                           '分类，细分品类为', c3.`name`, '。'),
    p.`price` = ROUND(CASE c1.`name`
        WHEN '手机数码' THEN 799 + RAND() * 6200
        WHEN '电脑办公' THEN 1299 + RAND() * 11700
        WHEN '家用电器' THEN 399 + RAND() * 8600
        WHEN '服饰鞋包' THEN 59 + RAND() * 1240
        WHEN '美妆个护' THEN 29 + RAND() * 870
        WHEN '食品生鲜' THEN 8 + RAND() * 191
        WHEN '运动户外' THEN 49 + RAND() * 1950
        WHEN '图书文娱' THEN 10 + RAND() * 289
        WHEN '家居日用' THEN 19 + RAND() * 1580
        WHEN '母婴玩具' THEN 29 + RAND() * 770
        ELSE 50 + RAND() * 950 END, 2),
    p.`original_price` = ROUND(p.`price` * 1.25, 2)
WHERE p.`id` < 501;

-- ---------- 1. 商品：每个三级类目均匀铺开 ----------

-- ---------- 2. 用户：新增 500 个（密码统一为 123456） ----------

-- ---------- 3. 行为：每个用户集中在自己偏好的类目上 ----------

-- ---------- 统计 ----------
SELECT (SELECT COUNT(*) FROM `product`)   AS products,
       (SELECT COUNT(*) FROM `user`)      AS users,
       (SELECT COUNT(*) FROM `behavior`)  AS behaviors,
       (SELECT COUNT(DISTINCT category_id) FROM `product`) AS used_categories;
